let maxFreq = function(s, maxLetters, minSize, maxSize)
{
    let sMap = new Map();
    let start = 0;
    let end = 0;
    let n = s.length;
    let maxOccurence = 0;
    let currentSize = 0;
    let dict = {};

    for (end=0; end<n; end++)
    {
        if (! sMap.has(s[end]))
        {
            sMap.set(s[end], 1);
        }
        else
        {
            sMap.set(s[end], sMap.get(s[end])+1);
            currentSize = end - start + 1;
            if (currentSize > maxSize)
            {
                start +=1; 
            }
        }
        while (sMap.size > maxLetters)
        {
            sMap.set(s[start], sMap.get(s[start])-1);
            if (sMap.get(s[start]) == 0)
            {
                sMap.delete(s[start]);
            }
            start +=1 ;
        }

        currentSize = end - start + 1;
        if (currentSize <= maxSize)
        {
            let currentWord = s.slice(start, end+1);
            if (!(currentWord in dict))
            {
                dict[currentWord] = 1;
            }
            else
            {
                dict[currentWord] = dict[currentWord] + 1;
            }
        }
        
    }
    // console.log(dict);
    for (let word in dict)
    {
        console.log(word, dict[word]);
    }
    maxOccurence = Math.max(...Object.values(dict));
    return maxOccurence
   
}
let s = 'aabcabcab';
// let s = "";
let maxLetters = 2;
let minSize = 2;
let maxSize = 3;

let output = maxFreq(s, maxLetters, minSize, maxSize);
console.log(output);